    if (i.n1 < 0 || i.n2 < 0 || i.F < 0) rep.invalid.push("INVALID INPUT — n1, n2 and F must be non-negative integers.");
    if (!isIntVal(i.n1) || !isIntVal(i.n2) || !isIntVal(i.F)) rep.invalid.push("INVALID INPUT — n1, n2 and F must be integers.");
    if (i.Ke1 <= -1) rep.invalid.push("INVALID INPUT — Ke1 must be greater than -1.");
    if (i.Ke2 <= -1) rep.invalid.push("INVALID INPUT — Ke2 must be greater than -1.");
    if (i.g1 <= -1) rep.invalid.push("INVALID INPUT — g1 must be greater than -1.");
