    if (typeof NI0 === "number" && NI0 < 0) rep.boundaries.push("SUPPORTED BOUNDARY — report Equity Value and P/B, not a cheap/expensive negative P/E.");
    if (i.NDE1 < 0 || i.NDE2 < 0) rep.boundaries.push("SUPPORTED BOUNDARY — verify required versus distributable cash. (Negative net debt = net cash.)");
