      if (v.expected.pb_blocks) for (var pb in v.expected.pb_blocks) cmp(v.name + ".pb." + pb, r.pb_blocks[pb], v.expected.pb_blocks[pb]);
      if (v.expected.funding) for (var fk in v.expected.funding) cmp(v.name + ".funding." + fk, r[fk], v.expected.funding[fk]);
